materialInfo.baseColor = baseColor.rgb;
materialInfo.ior = 1.5;
materialInfo.f0_dielectric = vec3(0.04);
materialInfo.specularWeight = 1.0;
materialInfo.f90 = vec3(1.0);
materialInfo.f90_dielectric = materialInfo.f90;
